@startuml

class Employee {
  + name : string
  + department : string
  + cardNumber : int
}

class GuestCard {
  + cardNumber : int
  + date : date
}

class Car {
  + licensePlate : string
}

class CarPark {
  + isFull : boolean
}

class Barrier {
  + isRaised : boolean
}

class CardReader {
  + isRecognized : boolean
}

class Reception {
  + collectGuestCard()
}

Employee "1" -- "1" CardReader : uses
GuestCard "1" -- "1" CardReader : uses
Car "1" -- "1" Barrier : passes through
CarPark "1" -- "*" Barrier : has
CarPark "1" -- "1" CardReader : has
Reception "1" -- "*" GuestCard : collects

@enduml

